import{_ as e,$ as a,v as r,y as n,f as s,i as l}from"./chunks/framework.D9rFsJdI.js";const b=JSON.parse('{"title":"Начало","description":"","frontmatter":{"title":"Начало","next":false},"headers":[],"relativePath":"posts/24052026/index.md","filePath":"posts/24052026/index.md"}'),o={name:"posts/24052026/index.md"};function i(d,t,h,c,p,f){return a(),r("div",null,[...t[0]||(t[0]=[n('<p><img src="'+s+'" alt="Изображение"></p><h1 id="разговоры-о-важном-итог" tabindex="-1">Разговоры о важном. Итог <a class="header-anchor" href="#разговоры-о-важном-итог" aria-label="Permalink to “Разговоры о важном. Итог”">​</a></h1><p><span style="color:#8C8C8C;"><strong>24.05.2026</strong> ・ <strong>n3kt0</strong></span></p><h2 id="мир-края" tabindex="-1"><span style="color:#cc4bffff;">Мир Края</span> <a class="header-anchor" href="#мир-края" aria-label="Permalink to “Мир Края”">​</a></h2><ul><li>Открытие мира Края произойдет летом в конце июня/начала июля по итогам голосовани. <a href="https://discord.com/channels/1202938978370584586/1497196470540046499" target="_blank" rel="noreferrer">опрос появится в Discord канале</a></li><li>Дабы сбалансировать шансы получения заветных элитр/шалкеров между игроками, первые 30 дней с момента открытия пользоваться элитрами в мире Края <strong>будет нельзя</strong>, тем не менее в Незере и Верхнем мире элитры работать будут.</li><li>Размер измерения будет <strong>10.000 в каждую сторону без каких-либо ограничений</strong>.</li></ul><h2 id="доступность-сервера" tabindex="-1"><span style="color:#4bff96ff;">Доступность сервера</span> <a class="header-anchor" href="#доступность-сервера" aria-label="Permalink to “Доступность сервера”">​</a></h2><ul><li>Примерно с середины лета новые игроки смогут попасть на сервер <strong>не только по заявке</strong>, но и за реальные деньги. При этом контроль заявок ужесточится: <table tabindex="0"><thead><tr><th>Заявка</th><th style="text-align:center;">Результат</th></tr></thead><tbody><tr><td>✔️Принята</td><td style="text-align:center;">Всё то же самое, что и раньше</td></tr><tr><td>❌Отклонена</td><td style="text-align:center;">У игрока будет шанс приобрести вход на сервер за 420 рублей, проходка покупается навсегда и является залогом доброчестной игры</td></tr></tbody></table></li></ul><h2 id="привилегии-за-материальную-поддержку" tabindex="-1"><span style="color:#fff34bff;">Привилегии за материальную поддержку</span> <a class="header-anchor" href="#привилегии-за-материальную-поддержку" aria-label="Permalink to “Привилегии за материальную поддержку”">​</a></h2><blockquote><p>Ничего, что как либо испортило или кардинально изменило бы геймплей/визуальную составляющую сервера добавляться - <strong>не будет</strong></p></blockquote><p>Если вы хотите поддержать сервер денежкой и получить за это что-то взамен, то информация для вас:</p><table tabindex="0"><thead><tr><th>Услуга</th><th style="text-align:center;">Описание</th><th style="text-align:right;">Срок</th></tr></thead><tbody><tr><td>Значки</td><td style="text-align:center;">Со временем появятся платные наборы значков у ника в табе и чате</td><td style="text-align:right;">Навсегда</td></tr><tr><td>Подписка «Меценат»</td><td style="text-align:center;">Большая часть функционала будет завязана на дискорд сервере, такой как: создание и настройка личной роли, буст по заработку коинов и косметические предметы в профиле. На майнкрафт сервере добавится только уникальный значок соответствующий данной роли</td><td style="text-align:right;">30 дней</td></tr></tbody></table><h2 id="откат-хранилищ-в-комнатах-испытании" tabindex="-1"><span style="color:#ff7e4bff;">Откат Хранилищ в Комнатах испытаний</span> <a class="header-anchor" href="#откат-хранилищ-в-комнатах-испытании" aria-label="Permalink to “Откат Хранилищ в Комнатах испытаний”">​</a></h2><p>Данное нововведение <strong>не планируется</strong></p><h2 id="мерч" tabindex="-1"><span style="color:#4beaffff;">Мерч</span> <a class="header-anchor" href="#мерч" aria-label="Permalink to “Мерч”">​</a></h2><p>Этим летом планируется наконец начать добавлять <strong>мерч</strong> в виде одежды для ваших скинов с символикой сервера и не только! Как это было на 14 февраля, например.</p><p><img src="'+l+'" alt="Изображение"></p>',16)])])}const _=e(o,[["render",i]]);export{b as __pageData,_ as default};
